import Orthogonal from "@orth/sdk";

const orthogonal = new Orthogonal({
  apiKey: process.env.ORTHOGONAL_API_KEY,
});

const result = await orthogonal.run({
  api: "tomba",
  path: "/v1/email-verifier",
  query: {
    "email": "example"
  }
});

console.log(result.data);

